package com.huy.enterprise.risk; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/risk-events") @RequiredArgsConstructor public class RiskEventController {private final RiskEventService service;@GetMapping List<RiskResponse> all(){return service.all();}@GetMapping("/{id}") RiskResponse get(@PathVariable UUID id){return service.get(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) RiskResponse create(@Valid @RequestBody RiskRequest r){return service.save(null,r);}@PutMapping("/{id}") RiskResponse update(@PathVariable UUID id,@Valid @RequestBody RiskRequest r){return service.save(id,r);}@PatchMapping("/{id}/status") RiskResponse status(@PathVariable UUID id,@Valid @RequestBody RiskStatusRequest r){return service.status(id,r);}}
